<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"; import { FileText, PackagePlus, Pause, Play, RefreshCw, Settings2, Square, Trash2 } from "@lucide/vue"; import { api } from "../api"; import { errorMessage, useUI } from "../ui"; import AppModal from "../components/AppModal.vue"; import EmptyState from "../components/EmptyState.vue"; import PageHeader from "../components/PageHeader.vue";
interface Item { id: string; name: string; image: string; state: string; status: string; ports: string; networks: string; managedBy?: string; cpuPercent?: string; memoryUsage?: string; memoryPercent?: string; networkIO?: string }
interface Detail { id: string; name: string; restartPolicy: string; maximumRetryCount: number; cpus: number; memoryBytes: number; managedBy?: string; composeProject?: string; environment: string[]; command: string[]; mounts: unknown[]; ports: unknown[]; networks: string[] }
const { notify, confirm } = useUI(); const items = ref<Item[]>([]); const available = ref(true); const loading = ref(false); const editor = ref<Detail | null>(null); const logs = ref<{ name: string; value: string } | null>(null); const form = reactive({ name: "", restartPolicy: "no", maximumRetryCount: 0, cpus: 0, memoryMb: 0 });
async function load() { loading.value = true; try { const data = await api<{ available: boolean; containers: Item[] | null }>("/api/admin/containers"); available.value = data.available; items.value = data.containers || []; } catch (e) { notify(errorMessage(e), "error"); } finally { loading.value = false; } }
async function action(item: Item, value: string) { loading.value = true; try { await api(`/api/admin/containers/${item.id}/${value}`, { method: "POST" }); notify("容器状态已更新"); await load(); } catch (e) { notify(errorMessage(e), "error"); } finally { loading.value = false; } }
async function open(item: Item) { try { const detail = await api<Detail>(`/api/admin/containers/${item.id}`); detail.networks ||= []; detail.environment ||= []; detail.command ||= []; detail.mounts ||= []; detail.ports ||= []; editor.value = detail; Object.assign(form, { name: detail.name, restartPolicy: detail.restartPolicy || "no", maximumRetryCount: detail.maximumRetryCount || 0, cpus: detail.cpus || 0, memoryMb: Math.round((detail.memoryBytes || 0) / 1048576) }); } catch (e) { notify(errorMessage(e), "error"); } }
async function save() { if (!editor.value) return; loading.value = true; try { await api(`/api/admin/containers/${editor.value.id}`, { method: "PUT", body: form }); notify("容器运行配置已更新"); editor.value = null; await load(); } catch (e) { notify(errorMessage(e), "error"); } finally { loading.value = false; } }
async function showLogs(item: Item) { try { const data = await api<{ logs: string }>(`/api/admin/containers/${item.id}/logs`); logs.value = { name: item.name, value: data.logs }; } catch (e) { notify(errorMessage(e), "error"); } }
async function remove(item: Item) { if (!await confirm(`删除容器 ${item.name}`, "容器将被强制停止并删除，挂载的数据卷不会删除。", "删除容器", true)) return; try { await api(`/api/admin/containers/${item.id}`, { method: "DELETE" }); notify("容器已删除"); await load(); } catch (e) { notify(errorMessage(e), "error"); } }
async function installDocker() { if (!await confirm("安装 Docker", "将通过 Alpine 软件源安装 Docker，设置为开机启动并立即启动服务。", "安装 Docker")) return; loading.value = true; try { await api("/api/admin/components/docker/install", { method: "POST" }); notify("Docker 已安装并启动"); await load(); } catch (e) { notify(errorMessage(e), "error"); } finally { loading.value = false; } }
onMounted(load);
</script>
<template><PageHeader title="容器管理" subtitle="Docker 容器状态、资源与运行配置" kicker="CONTAINERS"><button class="button" :disabled="loading" @click="load"><RefreshCw :class="{ spin: loading }" :size="16" />刷新</button></PageHeader><div v-if="!available" class="component-install-band"><div class="component-install-copy"><PackagePlus :size="22" /><div><strong>Docker 尚未安装</strong><span>安装后可在此管理容器、查看日志和调整运行配置。</span></div></div><button class="button primary" :disabled="loading" @click="installDocker"><RefreshCw v-if="loading" class="spin" :size="16" /><PackagePlus v-else :size="16" />安装 Docker</button></div><div v-else class="data-surface"><div class="table-scroll"><table class="data-table wide-table"><thead><tr><th>容器</th><th>镜像</th><th>状态</th><th>CPU / 内存</th><th>网络流量</th><th>端口</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ item.id.slice(0, 12) }}</small></td><td class="truncate-cell" :title="item.image">{{ item.image }}</td><td><span class="status-pill" :class="{ running: item.state === 'running', stopped: item.state !== 'running' }">{{ item.status }}</span></td><td><strong>{{ item.cpuPercent || '-' }}</strong><small>{{ item.memoryUsage || '-' }} · {{ item.memoryPercent || '-' }}</small></td><td>{{ item.networkIO || '-' }}</td><td class="truncate-cell" :title="item.ports">{{ item.ports || '-' }}</td><td><div class="row-actions"><button v-if="item.state !== 'running' && item.state !== 'paused'" class="icon-button" title="启动" @click="action(item, 'start')"><Play :size="16" /></button><button v-if="item.state === 'running'" class="icon-button" title="重启" @click="action(item, 'restart')"><RefreshCw :size="16" /></button><button v-if="item.state === 'running'" class="icon-button" title="暂停" @click="action(item, 'pause')"><Pause :size="16" /></button><button v-if="item.state === 'paused'" class="icon-button" title="恢复" @click="action(item, 'unpause')"><Play :size="16" /></button><button v-if="item.state === 'running' || item.state === 'paused'" class="icon-button" title="停止" @click="action(item, 'stop')"><Square :size="15" /></button><button class="icon-button" title="日志" @click="showLogs(item)"><FileText :size="16" /></button><button class="icon-button" title="配置" @click="open(item)"><Settings2 :size="16" /></button><button class="icon-button danger" title="删除" @click="remove(item)"><Trash2 :size="16" /></button></div></td></tr></tbody></table></div><EmptyState v-if="!loading && !items.length" message="暂无容器" /></div><AppModal v-if="editor" title="修改容器配置" wide :busy="loading" @close="editor = null" @submit="save"><div v-if="editor.managedBy" class="notice-band">此容器由 {{ editor.managedBy }} 管理，运行参数也应同步到编排配置。</div><div class="form-grid"><label class="field">容器名称<input v-model="form.name" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*"></label><label class="field">重启策略<select v-model="form.restartPolicy"><option value="no">不自动重启</option><option value="always">始终重启</option><option value="unless-stopped">除非手动停止</option><option value="on-failure">失败时重启</option></select></label><label class="field">CPU 限制（0 为不限）<input v-model.number="form.cpus" type="number" min="0" step="0.1"></label><label class="field">内存限制 MB（0 为不限）<input v-model.number="form.memoryMb" type="number" min="0"></label><label v-if="form.restartPolicy === 'on-failure'" class="field">最大重试次数<input v-model.number="form.maximumRetryCount" type="number" min="0" max="1000"></label></div><div class="detail-grid"><div><span>网络</span><code>{{ editor.networks.join(', ') || '-' }}</code></div><div><span>命令</span><code>{{ editor.command.join(' ') || '-' }}</code></div><div><span>环境变量</span><code>{{ editor.environment.length }} 项</code></div><div><span>挂载</span><code>{{ editor.mounts.length }} 项</code></div></div></AppModal><AppModal v-if="logs" :title="`${logs.name} 日志`" wide submit-label="关闭" @close="logs = null" @submit="logs = null"><pre class="log-view">{{ logs.value || '暂无日志' }}</pre><template #actions><button class="button primary" type="button" @click="logs = null">关闭</button></template></AppModal></template>
